mapper.select:
select count(*) from media_photo p inner join media_album a on a.id = p.album_id where p.album_id = #{albumId} and coalesce(p.missing, 0) = 0 and coalesce(p.hidden, 0) = 0
and (p.review_state is null or p.review_state = 'approved')
and coalesce(p.content_rating, a.content_rating) not in #{r}
